    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 65-year-old man with metastatic pancreatic cancer refuses further chemotherapy, expressing a desire to focus on palliative care. His family demands he continue treatment. Which principle supports the physician respecting the patient''s choice?', '["Beneficence", "Autonomy", "Justice", "Non-maleficence"]', 1, 'Autonomy refers to the patient''s right to self-determination and to make decisions about their own medical care, provided they have decision-making capacity.'),
    (v_topic_id, 'A physician recommends a laparoscopic cholecystectomy for a patient with symptomatic gallstones, believing it is the best course of action for the patient''s health. This action is driven by which principle?', '["Justice", "Autonomy", "Beneficence", "Non-maleficence"]', 2, 'Beneficence is the duty of the physician to act in the best interest of the patient and provide care that improves their well-being.'),
    (v_topic_id, 'During a surgery, a surgeon chooses a slightly more difficult technique because it carries a lower risk of post-operative infection, even though it takes longer. This is primarily an application of:', '["Justice", "Non-maleficence", "Autonomy", "Fidelity"]', 1, 'Non-maleficence is the principle of "First, do no harm," which includes minimizing risks and avoiding unnecessary harm to the patient.'),
    (v_topic_id, 'A hospital implements a protocol to ensure that all patients with identical clinical needs receive the same priority for ICU bed allocation, regardless of their insurance status. This is an example of:', '["Distributive Justice", "Beneficence", "Autonomy", "Veracity"]', 0, 'Justice, specifically distributive justice, refers to the fair and equitable distribution of healthcare resources and treatments.'),
    (v_topic_id, 'A 25-year-old woman with a history of intravenous drug use presents with endocarditis. The physician feels she will not comply with follow-up and considers withholding a valve replacement. Which principle is most directly challenged by this consideration?', '["Autonomy", "Non-maleficence", "Justice", "Paternalism"]', 2, 'Justice requires that patients be treated fairly and not be denied standard-of-care treatments based on lifestyle, perceived non-compliance, or social status.'),
    (v_topic_id, 'Which of the following describes the ethical concept of "Paternalism" in modern medicine?', '["Respecting the patient''s right to refuse treatment", "Making decisions for the patient based on what the physician believes is best, without the patient''s input", "Allocating resources based on the greatest need", "Telling the truth to the patient at all times"]', 1, 'Paternalism occurs when a physician overrides a patient''s autonomy, assuming a "parental" role to make decisions they believe are in the patient''s best interest.'),
    (v_topic_id, 'A patient asks about the success rate of a procedure. The surgeon provides an overly optimistic number to encourage the patient to undergo the surgery. Which ethical principle has been violated?', '["Justice", "Non-maleficence", "Veracity", "Confidentiality"]', 2, 'Veracity is the duty to tell the truth and be honest with patients, which is essential for informed consent.'),
    (v_topic_id, 'The "Rule of Double Effect" is often cited in end-of-life care. It states that an action with a good intent (e.g., pain relief) is ethically permissible even if it has a foreseeable bad effect (e.g., respiratory depression). Which principle is the "good intent" aligned with?', '["Justice", "Beneficence", "Autonomy", "Non-maleficence"]', 1, 'The intent to provide comfort and relief of suffering is an act of beneficence.'),
    (v_topic_id, 'In the Rule of Double Effect, which principle is technically "violated" by the foreseeable bad effect (e.g., hastening death)?', '["Autonomy", "Non-maleficence", "Justice", "Veracity"]', 1, 'The bad effect (harm) is a conflict with the principle of non-maleficence, but it is ethically accepted if the primary intent is beneficial and the harm is not the means to the good end.'),
    (v_topic_id, 'A patient demands a treatment that has been proven ineffective for their condition. The physician refuses to provide it. The physician''s refusal is primarily supported by which principle?', '["Autonomy", "Non-maleficence", "Justice", "Fidelity"]', 1, 'Physicians are not obligated to provide non-indicated or harmful treatments; non-maleficence and professional integrity override a patient''s "positive" right to demand any treatment.'),
    (v_topic_id, 'A 45-year-old Jehovah''s Witness patient is hemodynamically unstable and requires a blood transfusion. He is awake and reiterates his refusal of blood products. The physician respects this choice. This is an example of:', '["Paternalism overriding autonomy", "Autonomy overriding beneficence", "Beneficence overriding non-maleficence", "Justice overriding autonomy"]', 1, 'For a competent patient, the right to refuse treatment (Autonomy) takes precedence over the physician''s desire to provide a life-saving intervention (Beneficence).'),
    (v_topic_id, 'Which principle is the primary basis for the requirement of "Informed Consent"?', '["Beneficence", "Justice", "Autonomy", "Non-maleficence"]', 2, 'Informed consent is the practical application of respecting a patient''s autonomy.'),
    (v_topic_id, 'A physician notices a colleague is impaired by alcohol while on duty and reports them to the hospital board. This action is primarily guided by:', '["Autonomy", "Non-maleficence", "Justice", "Veracity"]', 1, 'Reporting an impaired colleague is essential to prevent harm to patients (Non-maleficence).'),
    (v_topic_id, 'The principle of "Fidelity" in medical ethics refers to:', '["The duty to tell the truth", "Keeping promises and being faithful to the patient-physician relationship", "Fairness in resource allocation", "Minimizing harm"]', 1, 'Fidelity involves loyalty, trust, and honoring the commitments made to a patient.'),
    (v_topic_id, 'A researcher ensures that the risks to participants in a clinical trial are outweighed by the potential benefits to those participants and society. This balance is an application of:', '["Autonomy and Justice", "Beneficence and Non-maleficence", "Veracity and Fidelity", "Confidentiality and Privacy"]', 1, 'In research, the risk-benefit ratio is a core application of beneficence and non-maleficence.'),
    (v_topic_id, 'A state health department mandates vaccination for all school-aged children to prevent an outbreak of measles. Which ethical framework often justifies this over individual autonomy?', '["Utilitarianism", "Deontology", "Virtue Ethics", "Egoism"]', 0, 'Utilitarianism focuses on the "greatest good for the greatest number," which is often the basis for public health laws.'),
    (v_topic_id, 'Which principle is most relevant when discussing the "Duty to Treat" during a global pandemic with limited personal protective equipment (PPE)?', '["Autonomy", "Beneficence vs. Self-Interest/Non-maleficence to self", "Justice", "Veracity"]', 1, 'The duty to treat involves the physician''s commitment to beneficence, balanced against the risk of harm to themselves and their families due to inadequate protection.'),
    (v_topic_id, 'A patient asks to see their own medical records. The physician provides them. This is a recognition of the patient''s:', '["Beneficence", "Autonomy", "Justice", "Non-maleficence"]', 1, 'Access to one''s own health information is a component of autonomy and self-determination.'),
    (v_topic_id, 'A physician provides care to an unconscious trauma patient in the emergency department without prior consent. This is ethically justified by:', '["Informed consent", "Presumed consent (Emergency Privilege)", "Justice", "Veracity"]', 1, 'In emergencies where the patient cannot consent and delay would cause serious harm, consent to life-saving treatment is presumed based on the principle of beneficence.'),
    (v_topic_id, 'Which principle is most central to the "Negative Right" to be left alone and free from unwanted medical intervention?', '["Beneficence", "Non-maleficence", "Autonomy", "Justice"]', 2, 'Autonomy is frequently described as a "negative right"—the right to refuse treatment.'),
    (v_topic_id, 'A "Standard of Care" is established to ensure all patients receive a minimum acceptable level of quality. This concept is most closely tied to:', '["Autonomy", "Non-maleficence", "Justice", "Fidelity"]', 1, 'Failing to meet the standard of care is a form of negligence and a violation of the duty to not harm patients.'),
    (v_topic_id, 'Which principle is primary when a physician protects a patient''s private health information from being shared with their employer?', '["Justice", "Beneficence", "Confidentiality (and Respect for Autonomy)", "Veracity"]', 2, 'Confidentiality is a specific duty derived from respect for a patient''s privacy and autonomy.'),
    (v_topic_id, 'A patient presents with a condition that the physician has a moral objection to treating (e.g., elective abortion). The physician refuses to perform the procedure but provides a timely referral to another provider. This manages the conflict between:', '["Physician Autonomy (Conscientious Objection) and Patient Access (Beneficence/Justice)", "Justice and Veracity", "Fidelity and Non-maleficence", "Autonomy and Paternalism"]', 0, 'This reflects the balance between a provider''s personal beliefs and their professional duty to ensure the patient receives legal medical care.'),
    (v_topic_id, 'The concept of "Egalitarianism" in healthcare justice suggests that:', '["Resources should be given to those who can pay", "Resources should be distributed equally to all members of society", "Resources should go to those with the best prognosis", "Physicians should decide who gets treatment"]', 1, 'Egalitarianism is a theory of justice emphasizing equal access and distribution for everyone.'),
    (v_topic_id, 'Which of the following scenarios best illustrates "Non-maleficence" in a clinical setting?', '["Providing a patient with a list of all possible treatment options", "Choosing a less invasive diagnostic test to avoid potential procedural complications", "Ensuring the patient''s room is clean", "Charging the same fee to all patients"]', 1, 'Choosing a safer path specifically to avoid harm is a direct application of non-maleficence.'),
    (v_topic_id, 'A physician admits a mistake to a patient, even though the patient was unaware of it. This is an act of:', '["Justice", "Autonomy", "Veracity", "Confidentiality"]', 2, 'Admitting errors is a requirement of veracity and professional transparency.'),
    (v_topic_id, 'A hospital triage system during a mass casualty event prioritizes patients who are likely to survive with immediate intervention over those who are unlikely to survive even with care. This is a application of:', '["Deontological Ethics", "Utilitarianism", "Virtue Ethics", "Autonomy"]', 1, 'Utilitarian triage aims to save the most lives possible with limited resources.'),
    (v_topic_id, 'The "Therapeutic Privilege" is a rare exception where a physician withholds information from a patient because they believe the disclosure would cause immediate and severe harm. This is a conflict between:', '["Beneficence/Non-maleficence and Autonomy/Veracity", "Justice and Fidelity", "Autonomy and Privacy", "None of the above"]', 0, 'It is a form of "benevolent paternalism" where the desire to prevent harm (non-maleficence) is weighed against the duty to tell the truth (veracity) and respect autonomy.'),
    (v_topic_id, 'In modern medical ethics, when a physician''s belief about what is "best" for the patient (Beneficence) conflicts with the patient''s own competent choice (Autonomy), which principle generally takes priority?', '["Beneficence", "Autonomy", "Justice", "Non-maleficence"]', 1, 'In US law and ethics, the competent patient''s autonomy is the "first among equals."'),
    (v_topic_id, 'A clinical trial is stopped early because the data clearly shows that the new drug is significantly better than the placebo. Continuing the trial would violate which principle for the placebo group?', '["Autonomy", "Justice", "Beneficence/Non-maleficence", "Veracity"]', 2, 'Once a treatment is proven superior, it is unethical to withhold it from the other group (beneficence) or continue to expose them to an inferior/harmful state (non-maleficence).'),
    (v_topic_id, 'Which of the following is an example of "Communitarianism" in health ethics?', '["Protecting individual privacy at all costs", "Focusing on the health of the community and social responsibilities", "Allowing patients to buy any medicine they want", "None of the above"]', 1, 'Communitarianism emphasizes the connection between the individual and the community, often prioritizing public health goals.'),
    (v_topic_id, 'A patient refuses to tell their partner that they have a serious communicable disease. The physician decides to notify the partner and the health department. This reflects a limit on the patient''s:', '["Autonomy and Confidentiality", "Beneficence", "Justice", "Veracity"]', 0, 'Public safety and the duty to warn (Harm Principle) can override an individual''s right to autonomy and confidentiality.'),
    (v_topic_id, 'The ethical principle that requires physicians to maintain their clinical skills and stay up-to-date with medical knowledge is primarily:', '["Autonomy", "Justice", "Non-maleficence/Beneficence", "Veracity"]', 2, 'Competence is essential to provide benefit (beneficence) and avoid harm from outdated practices (non-maleficence).'),
    (v_topic_id, 'Which concept refers to the obligation to provide care to the "undeserved" or those with the greatest health disparities?', '["Egalitarian Justice", "Social Justice", "Paternalism", "Autonomy"]', 1, 'Social justice focuses on addressing systemic inequalities in healthcare.'),
    (v_topic_id, 'A physician refuses to participate in a capital punishment execution. This is often based on the principle of:', '["Autonomy", "Justice", "Non-maleficence (and Professional Integrity)", "Veracity"]', 2, 'Medical involvement in executions is widely considered a violation of the fundamental duty to "do no harm" and use medical skills only for healing.'),
    (v_topic_id, 'Which principle is the basis for the "Right to a Second Opinion"?', '["Beneficence", "Justice", "Autonomy", "Non-maleficence"]', 2, 'A second opinion allows the patient to gather more information to make an autonomous decision.'),
    (v_topic_id, 'A patient is enrolled in a study. They are told they can withdraw at any time for any reason without penalty. This is a protection of their:', '["Justice", "Beneficence", "Autonomy", "Veracity"]', 2, 'The right to withdraw is a critical element of autonomous participation in research.'),
    (v_topic_id, 'When a doctor "Sugarcoats" a terminal diagnosis to spare the patient''s feelings, they are prioritizing:', '["Autonomy over Justice", "Beneficence/Non-maleficence over Veracity", "Justice over Fidelity", "Veracity over Autonomy"]', 1, 'The doctor is acting paternalistically, choosing to prevent emotional distress (non-maleficence) at the expense of honesty (veracity).'),
    (v_topic_id, 'A hospital "Ethics Committee" is typically composed of diverse professionals (doctors, nurses, chaplains, laypeople). The goal is to ensure a balanced perspective, reflecting the principle of:', '["Paternalism", "Procedural Justice", "Autonomy", "Beneficence"]', 1, 'Procedural justice involves having a fair and representative process for making difficult ethical decisions.'),
    (v_topic_id, 'A patient asks a physician to assist them in ending their life. In jurisdictions where this is illegal, the physician''s refusal is based on:', '["Autonomy", "Legal Justice and Professional Non-maleficence", "Beneficence", "Veracity"]', 1, 'Refusing an illegal act is a matter of legal compliance and adhering to professional standards of not causing death.'),
    (v_topic_id, 'Which principle requires that we do not treat people as a "means to an end" but as individuals with their own intrinsic value?', '["Utilitarianism", "Kantian Deontology (Respect for Persons/Autonomy)", "Hedonism", "Nihilism"]', 1, 'Kant''s categorical imperative is a cornerstone of the respect for autonomy.'),
    (v_topic_id, 'A doctor spends extra time explaining the risks and benefits of a complex surgery to a patient with low health literacy. This effort is driven by:', '["Justice", "Autonomy (enabling informed choice)", "Non-maleficence", "Veracity"]', 1, 'Ensuring the patient actually understands is the only way to truly respect their autonomy.'),
    (v_topic_id, 'A medical student is asked to perform a pelvic exam on an anesthetized patient who did not explicitly consent to being examined by a student. This is a violation of:', '["Beneficence", "Autonomy", "Justice", "Non-maleficence"]', 1, 'Performing procedures for educational purposes without patient consent is a violation of autonomy and dignity.'),
    (v_topic_id, 'The ethical principle that supports the use of "Advanced Directives" (like a Living Will) is:', '["Justice", "Beneficence", "Autonomy (Prospective Autonomy)", "Veracity"]', 2, 'Advanced directives allow a patient to exercise their autonomy even when they are no longer capable of making decisions.'),
    (v_topic_id, 'A rural hospital receives a government grant to provide free screenings for a prevalent local disease. This is an application of:', '["Autonomy", "Social Justice", "Non-maleficence", "Veracity"]', 1, 'Addressing health disparities in underserved populations is an act of social justice.'),
    (v_topic_id, 'Which principle is at the heart of the "Placebo Effect" ethical debate (i.e., whether it is okay to give a sugar pill if it might help the patient)?', '["Justice vs Autonomy", "Beneficence/Non-maleficence vs Veracity", "Fidelity vs Justice", "None of the above"]', 1, 'Providing a placebo involves a beneficial intent (beneficence) but requires deception (violating veracity).'),
    (v_topic_id, 'The "Four Boxes" method for clinical ethics cases (Jonsen, Siegler, Winslade) includes Clinical Indications, Patient Preferences, Quality of Life, and Contextual Features. Which box corresponds most to Autonomy?', '["Clinical Indications", "Patient Preferences", "Quality of Life", "Contextual Features"]', 1, 'Patient preferences are the direct expression of their autonomy.'),
    (v_topic_id, 'In the "Four Boxes" method, which box corresponds most to Justice?', '["Clinical Indications", "Patient Preferences", "Quality of Life", "Contextual Features"]', 3, 'Contextual features include financial issues, legal constraints, and resource allocation (Justice).'),
    (v_topic_id, 'A patient is prescribed a generic medication instead of a brand-name one because it is more cost-effective for the healthcare system while being equally effective. This is an application of:', '["Autonomy", "Non-maleficence", "Justice (Stewardship of resources)", "Veracity"]', 2, 'Choosing cost-effective care is part of the ethical stewardship of collective healthcare resources.'),
    (v_topic_id, 'A physician provides "Charity Care" to a patient who cannot afford to pay. This is primarily an act of:', '["Autonomy", "Justice/Beneficence", "Non-maleficence", "Veracity"]', 1, 'Charity care is a prosocial act of beneficence that addresses an individual instance of injustice in access to care.');
